STORY = [('chun_yuqiao', '直接说但是。', 'Skip straight to the word however.', [(744, '直接说但是')], ''), ('chun_yuqiao', '上周的报告看了吗？十二歌王收视率第一，超过第二名三个点，这是历史纪录。', "Did you read last week's report? Twelve Singers ranked number one in ratings, beating second place by three full points — a historic record.", [(753, '上周的报告看了吗'), (755, '超过第二名三个点'), (756, '这是历史')], ''), ('chun_yuqiao', '我们的战略合作也签约了，现在正是我们有余力开发新项目的时候。', 'Our overseas strategic partnership is signed too, so right now is the exact moment we have the strength to develop new projects.', [(757, '的战略合作'), (758, '也签约了'), (759, '现在正是我们有余力'), (760, '开发新项目的时候')], ''), ('chun_yuqiao', '比起资本风险，更关键的是机会成本。', 'Compared with capital risk, the far bigger issue is opportunity cost.', [(780, '比起资本风险'), (781, '更关键的'), (782, '是机会成本')], ''), ('chun_yuqiao', '现在投入原创制作，就必须要放弃海外版权项目。', 'Committing our team to original production right now means passing up licensed foreign formats.', [(783, '现在投入原创制作'), (784, '就必须要放弃'), (785, '海外版权项目')], ''), ('chun_yuqiao', '中国市场发展非常快，全世界的人都想挤进来，星天会是他们的第一选择。', 'The Chinese market is growing fast and everyone in the world wants in; naturally Xingtian is their first choice.', [(786, '中国市场发展非常快'), (787, '全世界的人都想挤进来'), (788, '星天'), (789, '会是他们的第一选择')], ''), ('chun_yuqiao', '可如果我们不跟他们合作，为了快速抢滩登陆，他们很有可能会跑到我们的竞争对手那边去。', 'Yet if we turn them down, in their rush to gain a foothold they may run straight into the arms of our competitors.', [(791, '我们不跟他们合作'), (792, '为了快速'), (792, '登陆'), (793, '他们很有可能会跑到'), (794, '我们的竞争对手那边去')], ''), ('chun_yuqiao', '到时候想回头就来不及了，所以这不是一条能回头的路。', 'By then it will be too late to turn back — so this is a road with no turnaround.', [(795, '到时候想回头'), (796, '就来不及了'), (798, '这不是一条'), (799, '能回头的路')], ''), ('chun_yuqiao', '你还用再问吗？你是我的老板，你了解我的。', 'Do you even need to ask for my stance? You are my boss — you know who I am.', [(802, '你还用再问吗'), (803, '你是我的老板'), (804, '你了解我的')], ''), ('chun_yuqiao', '我有把握让孤岛以同样的品质接棒十二歌王甚至超越。但是老板，留给你的时间不多。', "I am confident Lonely Island will match or surpass Twelve Singers in quality — though boss, you don't have much time left to decide.", [(810, '我有把握'), (811, '让孤岛以同样的品质'), (812, '甚至超越'), (813, '但是老板'), (814, '留给你的时间'), (815, '不多')], ''), ('kaiwen', '淳总，十二歌王今天走台，但是惠美怎么都联系不上，已经迟到三个小时了！', "Mr Chun, Twelve Singers has stage blocking today, except nobody can reach Huimei — she's already three hours late!", [(817, '淳总'), (818, '今天走台'), (819, '但是惠美怎么都联系不上'), (820, '已经迟到三个小时了')], ''), ('kaiwen', '你有没有什么办法找她一下？', 'Do you have any way to track her down?', [(821, '你有没有什么办法'), (822, '找她一下')], '')]
WALK = [(0, None, "'Skip straight to the word however.'"), (1, None, '"Did you read last week\'s report? Twelve Singers ranked number one in ratings, beating second place by three full points — a historic record."'), (2, None, "'Our overseas strategic partnership is signed too, so right now is the exact moment we have the strength to develop new projects.'"), (3, None, "'Compared with capital risk, the far bigger issue is opportunity cost.'"), (4, None, "'Committing our team to original production right now means passing up licensed foreign formats.'"), (5, None, "'The Chinese market is growing fast and everyone in the world wants in; naturally Xingtian is their first choice.'"), (6, None, "'Yet if we turn them down, in their rush to gain a foothold they may run straight into the arms of our competitors.'"), (7, None, "'By then it will be too late to turn back — so this is a road with no turnaround.'"), (8, None, "'Do you even need to ask for my stance? You are my boss — you know who I am.'"), (9, None, '"I am confident Lonely Island will match or surpass Twelve Singers in quality — though boss, you don\'t have much time left to decide."'), (10, None, '"Mr Chun, Twelve Singers has stage blocking today, except nobody can reach Huimei — she\'s already three hours late!"'), (11, None, "'Do you have any way to track her down?'")]
